'use strict';

var Float64Array = require( '@stdlib/array/float64' );
var ndarray2array = require( '@stdlib/ndarray/base/to-array' );
var dlange = require( './../lib' );

// Specify matrix meta data:
var shape = [ 3, 4 ];
var strides = [ 4, 1 ];
var offset = 0;
var order = 'row-major';

// Create a matrix stored in linear memory:
var A = new Float64Array( [ 1.0, 4.0, 7.0, 10.0, 2.0, 5.0, 8.0, 11.0, 3.0, 6.0, 9.0, 12.0 ] ); // eslint-disable-line max-len
console.log( ndarray2array( A, shape, strides, offset, order ) );

var work = new Float64Array( 3 );

// Calculate the infinity norm:
var out = dlange( order, 'infinity', shape[ 0 ], shape[ 1 ], A, strides[ 0 ], work );
console.log( 'Infinity norm: ', out );
